CookieOrLine::~CookieOrLine() {
  DestroyActive();
}

void CookieOrLine::set_cookie(CanonicalCookiePtr cookie) {
  if (tag_ == Tag::kCookie) {
    data_.cookie = std::move(cookie);
  } else {
    DestroyActive();
    tag_ = Tag::kCookie;
    new (&data_.cookie) CanonicalCookiePtr(
        std::move(cookie));
  }
}

void CookieOrLine::set_cookie_string(const std::string& cookie_string) {
  if (tag_ == Tag::kCookieString) {
    data_.cookie_string = std::move(cookie_string);
  } else {
    DestroyActive();
    tag_ = Tag::kCookieString;
    new (&data_.cookie_string) std::string(
        std::move(cookie_string));
  }
}


CookieOrLine::Union_::Union_(
    std::in_place_index_t<static_cast<size_t>(Tag::kCookie)>,
    CanonicalCookiePtr value)
    : cookie(std::move(value)) {}

